        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);
        ZipArchiveInputStream spyZais = spy(zais);

        ZipArchiveEntry ze = mock(ZipArchiveEntry.class);

        // To make ZipUtil.canHandleEntryData(ze) return true, 
