    @Test
    public void testCanReadEntryData_AllBranches() throws IOException {
        // Combining logic to ensure all branches (instanceof true/false, && true/false)

        // Branch 1: not instanceof ZipArchiveEntry
        InputStream is1 = new ByteArrayInputStream(new byte[0]);
        ZipArchiveInputStream zais1 = new ZipArchiveInputStream(is1);
        assertFalse(zais1.canReadEntryData(mock(ArchiveEntry.class)));
        zais1.close();

        // Branch 2: instanceof ZipArchiveEntry AND (ZipUtil == false OR supports == false)
        InputStream is2 = new ByteArrayInputStream(new byte[0]);
        ZipArchiveInputStream zais2 = new ZipArchiveInputStream(is2);
        ZipArchiveInputStream spyZais2 = spy(zais2);
        ZipArchiveEntry ze = mock(ZipArchiveEntry.class);

        // Force supportsDataDescriptorFor to false to test the && short-circuit/false result
        when(spyZais2.supportsDataDescriptorFor(ze)).thenReturn(false);
        assertFalse(spyZais2.canReadEntryData(ze));

        spyZais2.close();
    }
